const MAX_UPLOAD_BYTES = 5 * 1024 * 1024;
const ALLOWED_TYPES = new Set(['image/jpeg', 'image/png', 'image/gif', 'image/webp']);
const EDITOR_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Email Signature Editor</title>\n  <style>\n    :root{--bg:#eef2f7;--panel:#fff;--ink:#27313f;--muted:#647080;--line:#d8dee8;--accent:#23385f;--soft:#f7f9fc;--warn:#fff7df;--warnline:#e9cc78;--ok:#eaf8ef;--okline:#9bd7ae;--shadow:0 18px 50px rgba(17,24,39,.13);--radius:18px}\n    *{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f8fafc 0%,#e8edf5 100%);font-family:Segoe UI,Calibri,Arial,sans-serif;color:var(--ink)}\n    header{padding:22px 28px;background:#2f3338;color:#fff;display:flex;justify-content:space-between;gap:16px;align-items:center;box-shadow:0 8px 22px rgba(0,0,0,.16)}\n    h1{font-size:21px;margin:0}header p{margin:4px 0 0;color:#d9dde4;font-size:13px}.badge{font-size:12px;border:1px solid rgba(255,255,255,.25);border-radius:999px;padding:7px 10px;color:#f2f4f7;white-space:nowrap}\n    main{display:grid;grid-template-columns:430px minmax(430px,1fr);gap:18px;max-width:1540px;margin:0 auto;padding:18px}.panel{background:rgba(255,255,255,.94);border:1px solid #d9e0ea;border-radius:var(--radius);box-shadow:var(--shadow);overflow:hidden}.panel h2{font-size:15px;margin:0;padding:14px 16px;background:#f7f9fc;border-bottom:1px solid var(--line)}.section{padding:14px 16px;border-bottom:1px solid #edf1f6}.section:last-child{border-bottom:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field{margin-bottom:10px}label{display:block;font-size:12px;font-weight:700;color:#495363;margin-bottom:5px}input,select,textarea{width:100%;border:1px solid #cfd7e3;border-radius:10px;padding:9px 10px;font:14px Segoe UI,Calibri,Arial,sans-serif;color:#2f3338;background:#fff}textarea{resize:vertical}input[type=color]{height:38px;padding:4px}.row{display:flex;gap:8px;align-items:center}.btn{appearance:none;border:0;border-radius:11px;padding:10px 12px;background:#2f3338;color:white;font-weight:700;cursor:pointer}.btn.secondary{background:#edf1f6;color:#27313f;border:1px solid #cfd7e3}.btn:hover{filter:brightness(.98)}.hint,.mini{font-size:12px;color:var(--muted);line-height:1.45}.mini{font-size:11px;word-break:break-all}.warning,.ok{border-radius:12px;padding:10px 11px;font-size:12px;line-height:1.45;margin-top:8px}.warning{background:var(--warn);border:1px solid var(--warnline);color:#725600}.ok{background:var(--ok);border:1px solid var(--okline);color:#1f6b3a}.tabs{display:flex;gap:8px;flex-wrap:wrap;padding:12px 14px;border-bottom:1px solid var(--line);background:#f7f9fc}.tab{border:1px solid #ccd4e0;background:#fff;border-radius:999px;padding:8px 10px;font-size:12px;font-weight:700;color:#4b5565;cursor:pointer}.tab.active{background:#2f3338;color:#fff;border-color:#2f3338}.previewWrap{padding:18px;display:grid;grid-template-columns:1fr 1fr;gap:18px}.device{background:#1f242b;border-radius:30px;padding:14px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.12),0 20px 54px rgba(0,0,0,.22)}.device.pc{border-radius:16px;padding:10px}.screen{background:white;border-radius:20px;min-height:500px;overflow:auto;padding:18px}.pc .screen{border-radius:8px;min-height:360px}.caption{color:#e5e7eb;font-size:12px;font-weight:700;margin:0 0 10px 4px}.output{padding:0 18px 18px}.output textarea{height:260px;font-family:Consolas,Monaco,monospace;font-size:12px;line-height:1.45}.library{max-height:160px;overflow:auto;border:1px solid #d8dee8;border-radius:12px;padding:8px;background:#fbfcfe}.asset{display:flex;justify-content:space-between;gap:8px;align-items:center;font-size:12px;padding:6px;border-bottom:1px solid #edf0f5}.asset:last-child{border-bottom:0}.asset button{font-size:11px;padding:5px 7px}.templateNote{font-size:12px;color:#556273;background:#f5f7fb;border:1px solid #dfe5ee;border-radius:12px;padding:9px;margin-top:8px}@media(max-width:1000px){main{grid-template-columns:1fr}.previewWrap{grid-template-columns:1fr}.panel{border-radius:0}header{display:block}.badge{display:inline-block;margin-top:10px}}\n  </style>\n</head>\n<body>\n<header>\n  <div><h1>Email Signature Editor</h1><p>Start blank, host images, choose a template, preview clients, then copy visual output or HTML.</p></div>\n  <span class=\"badge\">Default path: /editor/</span>\n</header>\n<main>\n  <aside class=\"panel\">\n    <h2>Signature Content</h2>\n    <div class=\"section grid\">\n      <div class=\"field\"><label>Name</label><input id=\"name\" placeholder=\"Full name\"></div>\n      <div class=\"field\"><label>Title</label><input id=\"title\" placeholder=\"Job title\"></div>\n      <div class=\"field\"><label>Company</label><input id=\"company\" placeholder=\"Company name\"></div>\n      <div class=\"field\"><label>Department / Location</label><input id=\"station\" placeholder=\"Optional\"></div>\n      <div class=\"field\"><label>Email</label><input id=\"email\" placeholder=\"name@example.com\"></div>\n      <div class=\"field\"><label>Cell</label><input id=\"cell\" placeholder=\"000.000.0000\"></div>\n      <div class=\"field\"><label>Office</label><input id=\"office\" placeholder=\"Optional\"></div>\n      <div class=\"field\"><label>Address</label><input id=\"address\" placeholder=\"Optional\"></div>\n      <div class=\"field\"><label>Website URL</label><input id=\"website\" placeholder=\"https://example.com\"></div>\n      <div class=\"field\"><label>Website Label</label><input id=\"websiteLabel\" placeholder=\"example.com\"></div>\n    </div>\n\n    <h2>Template & Style</h2>\n    <div class=\"section\">\n      <div class=\"grid\">\n        <div class=\"field\"><label>Template</label><select id=\"template\"></select></div>\n        <div class=\"field\"><label>Font</label><select id=\"font\">\n          <option value=\"Segoe UI, Calibri, Arial, sans-serif\">Segoe UI</option>\n          <option value=\"Calibri, Arial, sans-serif\">Calibri</option>\n          <option value=\"Arial, Helvetica, sans-serif\">Arial</option>\n          <option value=\"Verdana, Geneva, sans-serif\">Verdana</option>\n          <option value=\"Trebuchet MS, Arial, sans-serif\">Trebuchet MS</option>\n          <option value=\"Tahoma, Geneva, sans-serif\">Tahoma</option>\n          <option value=\"Georgia, Times New Roman, serif\">Georgia</option>\n          <option value=\"Times New Roman, Times, serif\">Times New Roman</option>\n          <option value=\"Custom / web font\">Custom / web font</option>\n        </select></div>\n        <div class=\"field\"><label>Text Color</label><input id=\"textColor\" type=\"color\" value=\"#4a4a4a\"></div>\n        <div class=\"field\"><label>Name Color</label><input id=\"nameColor\" type=\"color\" value=\"#3a3a3a\"></div>\n        <div class=\"field\"><label>Link Color</label><input id=\"linkColor\" type=\"color\" value=\"#3f6f9f\"></div>\n        <div class=\"field\"><label>Divider / Accent</label><input id=\"lineColor\" type=\"color\" value=\"#cfcfcf\"></div>\n        <div class=\"field\"><label>Signature Width</label><select id=\"width\"><option value=\"320\">320 px</option><option value=\"360\">360 px</option><option value=\"390\" selected>390 px</option><option value=\"420\">420 px</option><option value=\"520\">520 px</option></select></div>\n        <div class=\"field\"><label>Image Width</label><select id=\"imgWidth\"><option value=\"260\">260 px</option><option value=\"300\">300 px</option><option value=\"320\">320 px</option><option value=\"360\" selected>360 px</option><option value=\"420\">420 px</option></select></div>\n      </div>\n      <div id=\"templateNote\" class=\"templateNote\"></div>\n      <div id=\"supportWarn\" class=\"warning\"></div>\n    </div>\n\n    <h2>Hosted Images</h2>\n    <div class=\"section\">\n      <div class=\"field\"><label>Upload image to this Worker</label><input id=\"uploadFile\" type=\"file\" accept=\"image/png,image/jpeg,image/gif,image/webp\"></div>\n      <div class=\"row\"><input id=\"uploadName\" placeholder=\"image-name, e.g. company-banner\"><button class=\"btn\" id=\"uploadBtn\">Upload</button></div>\n      <div id=\"uploadStatus\" class=\"hint\" style=\"margin-top:8px\">Uploaded images are served from <strong>/u/name.jpg</strong>.</div>\n      <div style=\"height:10px\"></div>\n      <div class=\"field\"><label>Image 1 URL</label><input id=\"logoUrl\" placeholder=\"Paste or upload an image URL\"></div>\n      <div class=\"field\"><label>Image 1 Click URL</label><input id=\"logoLink\" placeholder=\"Optional link when clicked\"></div>\n      <div class=\"field\"><label>Image 2 URL</label><input id=\"careerUrl\" placeholder=\"Optional second image URL\"></div>\n      <div class=\"field\"><label>Image 2 Click URL</label><input id=\"careerLink\" placeholder=\"Optional link when clicked\"></div>\n      <button class=\"btn secondary\" id=\"refreshAssets\">Refresh uploaded library</button>\n      <div class=\"library\" id=\"assetLibrary\" style=\"margin-top:8px\"><span class=\"hint\">No uploaded assets loaded yet.</span></div>\n    </div>\n  </aside>\n\n  <section class=\"panel\">\n    <h2>Visualizers</h2>\n    <div class=\"tabs\" id=\"tabs\">\n      <button class=\"tab active\" data-view=\"iphone\">iPhone Mail</button>\n      <button class=\"tab\" data-view=\"outlookios\">Outlook iOS</button>\n      <button class=\"tab\" data-view=\"outlookpc\">Outlook PC</button>\n      <button class=\"tab\" data-view=\"gmailios\">Gmail iOS</button>\n      <button class=\"tab\" data-view=\"gmailpc\">Gmail PC</button>\n    </div>\n    <div class=\"previewWrap\">\n      <div class=\"device\" id=\"device\"><p class=\"caption\" id=\"caption\">iPhone Mail preview</p><div class=\"screen\" id=\"preview\"></div></div>\n      <div class=\"device pc\"><p class=\"caption\">Copy/paste visual</p><div class=\"screen\"><div id=\"copyVisual\" contenteditable=\"true\" style=\"outline:0\"></div></div></div>\n    </div>\n    <div class=\"output\">\n      <div class=\"row\" style=\"justify-content:space-between;margin-bottom:8px\"><strong>Generated HTML</strong><div><button class=\"btn secondary\" id=\"copyVisualBtn\">Copy Visual</button> <button class=\"btn\" id=\"copyHtmlBtn\">Copy HTML</button></div></div>\n      <textarea id=\"htmlOut\" spellcheck=\"false\"></textarea>\n    </div>\n  </section>\n</main>\n<script>\nconst $ = id => document.getElementById(id);\nconst templates = {\n  classic:{label:'Classic dark gray',note:'Clean dark-gray text, simple divider, compact corporate feel.',font:'Segoe UI, Calibri, Arial, sans-serif',text:'#4a4a4a',name:'#3a3a3a',link:'#3f6f9f',line:'#cfcfcf',layout:'stack',nameSize:20,bodySize:13,width:390,img:360,divider:true,labels:true},\n  executive:{label:'Executive slate',note:'Heavier name, slate accent, strong but still Outlook-safe.',font:'Georgia, Times New Roman, serif',text:'#3f444a',name:'#25282c',link:'#566b86',line:'#8a96a6',layout:'stack',nameSize:23,bodySize:13,width:420,img:360,divider:true,labels:true},\n  compact:{label:'Compact mobile',note:'Narrower, lighter, better for phone-heavy signatures.',font:'Calibri, Arial, sans-serif',text:'#4b5563',name:'#333333',link:'#386b8f',line:'#d7d7d7',layout:'stack',nameSize:18,bodySize:12,width:360,img:320,divider:true,labels:false},\n  card:{label:'Left-bar card',note:'Uses a vertical accent bar and clean contact block.',font:'Segoe UI, Calibri, Arial, sans-serif',text:'#444444',name:'#2d3748',link:'#1f6f8b',line:'#1f6f8b',layout:'leftbar',nameSize:21,bodySize:13,width:420,img:360,divider:false,labels:true},\n  minimal:{label:'Minimal no-labels',note:'Very simple text-first layout without field labels.',font:'Arial, Helvetica, sans-serif',text:'#444444',name:'#222222',link:'#444444',line:'#dddddd',layout:'stack',nameSize:19,bodySize:13,width:390,img:320,divider:false,labels:false},\n  blue:{label:'Blue aviation',note:'Blue name/accent with a crisp aviation/corporate look.',font:'Verdana, Geneva, sans-serif',text:'#3e4752',name:'#1f4e79',link:'#1f4e79',line:'#1f4e79',layout:'stack',nameSize:20,bodySize:12,width:420,img:360,divider:true,labels:true},\n  gold:{label:'Gold accent',note:'Warm gold divider and understated premium style.',font:'Trebuchet MS, Arial, sans-serif',text:'#4c4c4c',name:'#303030',link:'#8a6d1d',line:'#b89b3f',layout:'stack',nameSize:21,bodySize:13,width:420,img:360,divider:true,labels:true},\n  green:{label:'Operations green',note:'Green accent for operations/safety-oriented branding.',font:'Tahoma, Geneva, sans-serif',text:'#3f4b46',name:'#1f3f31',link:'#246b48',line:'#4f8f64',layout:'leftbar',nameSize:20,bodySize:12,width:420,img:360,divider:false,labels:true},\n  modern:{label:'Modern split',note:'Name and role separated from contact info in a two-column table.',font:'Segoe UI, Calibri, Arial, sans-serif',text:'#3e4650',name:'#202938',link:'#2b647c',line:'#d4dae3',layout:'split',nameSize:20,bodySize:12,width:520,img:360,divider:true,labels:false},\n  formal:{label:'Formal serif',note:'Traditional serif style for a more formal signature.',font:'Times New Roman, Times, serif',text:'#404040',name:'#202020',link:'#365f91',line:'#bcbcbc',layout:'stack',nameSize:22,bodySize:13,width:420,img:360,divider:true,labels:true}\n};\nconst fields = ['name','title','company','station','email','cell','office','address','website','websiteLabel','template','font','textColor','nameColor','linkColor','lineColor','width','imgWidth','logoUrl','logoLink','careerUrl','careerLink'];\nObject.entries(templates).forEach(([key,t])=>{const o=document.createElement('option');o.value=key;o.textContent=t.label;$('template').appendChild(o);});\nfunction esc(s){return String(s||'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));}\nfunction phoneHref(s){return String(s||'').replace(/[^0-9+]/g,'');}\nfunction line(text){return text ? esc(text) : '';}\nfunction applyTemplate(){const t=templates[$('template').value];$('font').value=t.font;$('textColor').value=t.text;$('nameColor').value=t.name;$('linkColor').value=t.link;$('lineColor').value=t.line;$('width').value=String(t.width);$('imgWidth').value=String(t.img);render();}\nfunction contactRows(v,t){\n  const rows=[];\n  if(v.email) rows.push(t.labels ? '<div><strong style=\"color:'+v.nameColor+';\">Email:</strong> <a href=\"mailto:'+esc(v.email)+'\" style=\"color:'+v.linkColor+'; text-decoration:none;\">'+esc(v.email)+'</a></div>' : '<div><a href=\"mailto:'+esc(v.email)+'\" style=\"color:'+v.linkColor+'; text-decoration:none;\">'+esc(v.email)+'</a></div>');\n  if(v.cell || v.office){let p=[]; if(v.cell)p.push((t.labels?'<strong style=\"color:'+v.nameColor+';\">Cell:</strong> ':'')+'<a href=\"tel:'+phoneHref(v.cell)+'\" style=\"color:'+v.linkColor+'; text-decoration:none;\">'+esc(v.cell)+'</a>'); if(v.office)p.push((t.labels?'<strong style=\"color:'+v.nameColor+';\">Office:</strong> ':'')+'<a href=\"tel:'+phoneHref(v.office)+'\" style=\"color:'+v.linkColor+'; text-decoration:none;\">'+esc(v.office)+'</a>'); rows.push('<div>'+p.join('<span style=\"color:#777777;\"> | </span>')+'</div>');}\n  if(v.address) rows.push('<div>'+(t.labels?'<strong style=\"color:'+v.nameColor+';\">Address:</strong> ':'')+'<span style=\"color:'+v.textColor+';\">'+esc(v.address)+'</span></div>');\n  if(v.website && v.websiteLabel) rows.push('<div><a href=\"'+esc(v.website)+'\" target=\"_blank\" style=\"color:'+v.linkColor+'; text-decoration:none;\">'+esc(v.websiteLabel)+'</a></div>');\n  return rows.join('');\n}\nfunction imageRow(url,link,width,alt,pad){if(!url)return '';const img='<img src=\"'+esc(url)+'\" width=\"'+esc(width)+'\" alt=\"'+esc(alt)+'\" style=\"display:block; border:0; outline:none; text-decoration:none; width:'+esc(width)+'px; max-width:'+esc(width)+'px; height:auto;\" />';return '<tr><td style=\"padding:'+pad+';\"><a href=\"'+esc(link||'#')+'\" target=\"_blank\" style=\"text-decoration:none;\">'+img+'</a></td></tr>';}\nfunction buildHtml(){\n  const v=Object.fromEntries(fields.map(f=>[f,$(f).value])); const t=templates[v.template];\n  const font = v.font==='Custom / web font'?'Arial, Helvetica, sans-serif':v.font;\n  const titleBlock = '<div style=\"font-size:'+t.nameSize+'px; line-height:'+(t.nameSize+4)+'px; font-weight:700; color:'+v.nameColor+';\">'+line(v.name)+'</div>'+\n    (v.title?'<div style=\"font-size:14px; line-height:19px; font-weight:600; color:'+v.textColor+';\">'+line(v.title)+'</div>':'')+\n    (v.company?'<div style=\"font-size:14px; line-height:19px; color:'+v.textColor+';\">'+line(v.company)+'</div>':'')+\n    (v.station?'<div style=\"font-size:13px; line-height:18px; color:'+v.textColor+';\">'+line(v.station)+'</div>':'');\n  const contacts = contactRows(v,t);\n  const divider = t.divider ? '<tr><td style=\"padding:0 0 9px 0;\"><div style=\"height:1px; background:'+v.lineColor+'; width:'+Math.min(Number(v.imgWidth),Number(v.width)-30)+'px; max-width:100%;\"></div></td></tr>' : '';\n  const imgs = imageRow(v.logoUrl,v.logoLink,v.imgWidth,'Signature image 1','0 0 4px 0') + imageRow(v.careerUrl,v.careerLink,v.imgWidth,'Signature image 2','0 0 6px 0');\n  let inner='';\n  if(t.layout==='split') inner='<tr><td style=\"padding:0 16px 8px 0; vertical-align:top; width:48%;\">'+titleBlock+'</td><td style=\"padding:0 0 8px 16px; vertical-align:top; border-left:1px solid '+v.lineColor+'; font-size:'+t.bodySize+'px; line-height:'+(t.bodySize+7)+'px; color:'+v.textColor+';\">'+contacts+'</td></tr>'+imgs;\n  else if(t.layout==='leftbar') inner='<tr><td style=\"border-left:4px solid '+v.lineColor+'; padding:0 0 10px 12px;\">'+titleBlock+'</td></tr><tr><td style=\"padding:0 0 10px 12px; font-size:'+t.bodySize+'px; line-height:'+(t.bodySize+7)+'px; color:'+v.textColor+';\">'+contacts+'</td></tr>'+imgs;\n  else inner='<tr><td style=\"padding:0 0 8px 0;\">'+titleBlock+'</td></tr>'+divider+'<tr><td style=\"padding:0 0 10px 0; font-size:'+t.bodySize+'px; line-height:'+(t.bodySize+7)+'px; color:'+v.textColor+';\">'+contacts+'</td></tr>'+imgs;\n  return '<table cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"font-family:'+esc(font)+'; color:'+v.textColor+'; width:'+v.width+'px; max-width:'+v.width+'px;\">'+inner+'</table>';\n}\nlet activeView='iphone';\nfunction iphoneMailPreview(signatureHtml){\n  const now = new Date();\n  const mins = String(now.getMinutes()).padStart(2,'0');\n  const time = now.getHours()+':'+mins;\n  return '<div style=\"width:390px;max-width:100%;min-height:690px;background:#ffffff;color:#111;font-family:-apple-system,BlinkMacSystemFont,'SF Pro Text','Helvetica Neue',Arial,sans-serif;overflow:hidden;\">'\n    + '<div style=\"height:34px;padding:11px 18px 0 22px;font-size:13px;font-weight:600;color:#111;display:flex;justify-content:space-between;align-items:flex-start;\"><span>'+time+'</span><span style=\"font-size:12px;letter-spacing:1px;\">▮▮▮  Wi‑Fi  🔋</span></div>'\n    + '<div style=\"height:45px;border-bottom:1px solid #d8d8dc;display:flex;align-items:center;justify-content:space-between;padding:0 14px;font-size:17px;background:#fff;\"><span style=\"color:#007aff;font-weight:400;\">Cancel</span><span style=\"font-weight:600;color:#111;\">New Message</span><span style=\"color:#007aff;font-weight:600;opacity:.55;\">Send</span></div>'\n    + '<div style=\"font-size:16px;background:#fff;\">'\n      + '<div style=\"display:flex;align-items:center;min-height:38px;border-bottom:1px solid #e5e5ea;padding:0 14px;\"><span style=\"width:72px;color:#8e8e93;\">To:</span><span style=\"color:#c7c7cc;\">Recipient</span><span style=\"margin-left:auto;color:#007aff;font-size:24px;line-height:1;\">⊕</span></div>'\n      + '<div style=\"display:flex;align-items:center;min-height:38px;border-bottom:1px solid #e5e5ea;padding:0 14px;\"><span style=\"width:72px;color:#8e8e93;\">Cc/Bcc:</span></div>'\n      + '<div style=\"display:flex;align-items:center;min-height:38px;border-bottom:1px solid #e5e5ea;padding:0 14px;\"><span style=\"width:72px;color:#8e8e93;\">Subject:</span></div>'\n    + '</div>'\n    + '<div style=\"padding:14px 14px 0 14px;background:#fff;min-height:495px;font-size:16px;line-height:22px;color:#111;\">'\n      + '<div style=\"height:74px;color:#111;position:relative;\"><span style=\"display:inline-block;width:2px;height:22px;background:#007aff;border-radius:2px;vertical-align:top;\"></span></div>'\n      + '<div style=\"font-family:inherit;max-width:362px;overflow:visible;\">'+signatureHtml+'</div>'\n    + '</div>'\n    + '<div style=\"height:22px;background:#fff;display:flex;justify-content:center;align-items:center;\"><div style=\"width:134px;height:5px;border-radius:999px;background:#111;opacity:.9;\"></div></div>'\n  + '</div>';\n}\nfunction clientPreviewHtml(signatureHtml){\n  if(activeView==='iphone') return iphoneMailPreview(signatureHtml);\n  return signatureHtml;\n}\nfunction render(){\n  const html=buildHtml(); $('htmlOut').value=html; $('copyVisual').innerHTML=html; $('preview').innerHTML=clientPreviewHtml(html);\n  const t=templates[$('template').value]; $('templateNote').textContent=t.note;\n  const warn=[]; if($('font').value==='Custom / web font')warn.push('Outlook desktop usually ignores web fonts. The generated HTML falls back to Arial.');\n  if(['Georgia, Times New Roman, serif','Times New Roman, Times, serif'].includes($('font').value)) warn.push('Serif fonts are generally supported, but mobile clients may substitute slightly different font metrics.');\n  if(Number($('imgWidth').value)>360)warn.push('Images wider than 360 px can look oversized on phones and narrow Outlook panes.');\n  if(activeView==='iphone') warn.push('iPhone Mail preview now shows the native compose window, field rows, iOS spacing, and mobile-width body area. The actual email can still vary slightly by iOS version, dark mode, and user text-size settings.');\n  warn.push('Outlook PC uses Microsoft Word rendering. Tables and inline styles are safest. Gradients, shadows, rounded corners, flex layouts, CSS variables, and web fonts may appear different.');\n  $('supportWarn').innerHTML=warn.join('<br>');\n}\nfunction setView(view){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); activeView=view; const d=$('device'),s=$('preview'),c=$('caption'); d.className=view.includes('pc')?'device pc':'device'; const names={iphone:'iPhone Mail compose preview',outlookios:'Outlook iOS preview',outlookpc:'Outlook PC preview',gmailios:'Gmail iOS preview',gmailpc:'Gmail PC preview'}; c.textContent=names[view]; s.style.fontFamily=view==='iphone'?'-apple-system, BlinkMacSystemFont, Segoe UI, Arial, sans-serif':(view==='outlookpc'?'Calibri, Arial, sans-serif':'Segoe UI, Arial, sans-serif'); s.style.width=view.includes('pc')?'100%':'390px'; s.style.maxWidth='100%'; s.style.minHeight=view.includes('pc')?'360px':'520px'; s.style.padding=view==='iphone'?'0':'18px'; s.style.background=view==='iphone'?'#ffffff':'#ffffff'; s.style.overflow=view==='iphone'?'hidden':'auto'; render();}\nasync function copyText(text){await navigator.clipboard.writeText(text);}\nasync function loadAssets(){const box=$('assetLibrary'); box.innerHTML='<span class=\"hint\">Loading...</span>'; try{const r=await fetch('/api/list'); const data=await r.json(); if(!data.uploads||!data.uploads.length){box.innerHTML='<span class=\"hint\">No uploaded images yet.</span>';return;} box.innerHTML=data.uploads.map(a=>'<div class=\"asset\"><div><strong>'+esc(a.name)+'</strong><div class=\"mini\">'+esc(a.url)+'</div></div><button class=\"btn secondary\" data-url=\"'+esc(a.url)+'\">Use</button></div>').join(''); box.querySelectorAll('button').forEach(b=>b.onclick=()=>{$('logoUrl').value=b.dataset.url;render();});}catch(e){box.innerHTML='<span class=\"hint\">Could not load uploads. KV may not be configured yet.</span>';}}\nasync function upload(){const f=$('uploadFile').files[0]; if(!f){$('uploadStatus').innerHTML='<div class=\"warning\">Choose an image first.</div>';return;} const fd=new FormData(); fd.append('image',f); fd.append('name',$('uploadName').value||f.name); $('uploadStatus').textContent='Uploading...'; try{const r=await fetch('/api/upload',{method:'POST',body:fd}); const data=await r.json(); if(!r.ok)throw new Error(data.error||'Upload failed'); $('uploadStatus').innerHTML='<div class=\"ok\">Hosted image created:<br><span class=\"mini\">'+esc(data.url)+'</span></div>'; $('logoUrl').value=data.url; render(); loadAssets();}catch(e){$('uploadStatus').innerHTML='<div class=\"warning\">'+esc(e.message)+'<br>Make sure the Cloudflare KV namespace is configured.</div>';}}\nfields.forEach(f=>$(f).addEventListener('input',render)); $('template').addEventListener('change',applyTemplate); $('tabs').addEventListener('click',e=>{if(e.target.matches('.tab'))setView(e.target.dataset.view)}); $('copyHtmlBtn').onclick=()=>copyText($('htmlOut').value); $('copyVisualBtn').onclick=()=>{const range=document.createRange();range.selectNodeContents($('copyVisual'));const sel=getSelection();sel.removeAllRanges();sel.addRange(range);document.execCommand('copy');sel.removeAllRanges();}; $('uploadBtn').onclick=upload; $('refreshAssets').onclick=loadAssets;\n$('template').value='classic'; setView('iphone'); render(); loadAssets();\n</script>\n</body>\n</html>\n";
const STATIC_HTML = {
  '/editor/': EDITOR_HTML,
  '/calebowen/': "<html><head><meta charset=\"utf-8\"><title>Caleb Owen Signature Assets</title></head><body style=\"font-family:Arial,Helvetica,sans-serif;padding:24px\"><h1>Caleb Owen Signature Assets</h1><img src=\"/calebowen/primeflight-logo.png\" width=\"360\" style=\"display:block;border:0;width:360px;max-width:100%;height:auto\"></body></html>",
  '/calebowen': "<html><head><meta charset=\"utf-8\"><title>Caleb Owen Signature Assets</title></head><body style=\"font-family:Arial,Helvetica,sans-serif;padding:24px\"><h1>Caleb Owen Signature Assets</h1><img src=\"/calebowen/primeflight-logo.png\" width=\"360\" style=\"display:block;border:0;width:360px;max-width:100%;height:auto\"></body></html>",
  '/calebblaber/': "<html><head><meta charset=\"utf-8\"><title>Caleb Blaber Signature Assets</title></head><body style=\"font-family:Arial,Helvetica,sans-serif;padding:24px\"><h1>Caleb Blaber Signature Assets</h1><a href=\"https://www.primeflight.com/\"><img src=\"/calebblaber/primeflight-family.jpg\" width=\"360\" style=\"display:block;border:0;width:360px;max-width:100%;height:auto\"></a><a href=\"https://primeflight.com/careers\"><img src=\"/calebblaber/career-banner.jpg\" width=\"360\" style=\"display:block;border:0;width:360px;max-width:100%;height:auto;margin-top:3px\"></a></body></html>",
  '/calebblaber': "<html><head><meta charset=\"utf-8\"><title>Caleb Blaber Signature Assets</title></head><body style=\"font-family:Arial,Helvetica,sans-serif;padding:24px\"><h1>Caleb Blaber Signature Assets</h1><a href=\"https://www.primeflight.com/\"><img src=\"/calebblaber/primeflight-family.jpg\" width=\"360\" style=\"display:block;border:0;width:360px;max-width:100%;height:auto\"></a><a href=\"https://primeflight.com/careers\"><img src=\"/calebblaber/career-banner.jpg\" width=\"360\" style=\"display:block;border:0;width:360px;max-width:100%;height:auto;margin-top:3px\"></a></body></html>"
};
const STATIC_ASSETS = {"/calebowen/primeflight-logo.png": {"contentType": "image/png", "base64": ""}, "/calebblaber/primeflight-family.jpg": {"contentType": "image/jpeg", "base64": ""}, "/calebblaber/career-banner.jpg": {"contentType": "image/jpeg", "base64": ""}};

function safeName(input) {
  return String(input || 'signature-image').trim().toLowerCase().replace(/\.[a-z0-9]+$/i, '').replace(/[^a-z0-9-_]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) || 'signature-image';
}
function extFromType(type) { if (type === 'image/png') return 'png'; if (type === 'image/gif') return 'gif'; if (type === 'image/webp') return 'webp'; return 'jpg'; }
function jsonResponse(data, status = 200) { return new Response(JSON.stringify(data, null, 2), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } }); }
function htmlResponse(html) { return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'public, max-age=60' } }); }
function staticAssetResponse(asset) {
  const binary = atob(asset.base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Response(bytes, { headers: { 'content-type': asset.contentType, 'cache-control': 'public, max-age=31536000, immutable', 'access-control-allow-origin': '*' } });
}
async function serveUpload(request, env) {
  if (!env.SIG_ASSETS) return jsonResponse({ error: 'Missing Cloudflare KV binding: SIG_ASSETS' }, 500);
  const form = await request.formData();
  const file = form.get('image');
  const rawName = form.get('name');
  if (!file || typeof file === 'string') return jsonResponse({ error: 'No image file was uploaded.' }, 400);
  if (!ALLOWED_TYPES.has(file.type)) return jsonResponse({ error: 'Unsupported image type. Use JPG, PNG, GIF, or WEBP.' }, 400);
  if (file.size > MAX_UPLOAD_BYTES) return jsonResponse({ error: 'Image is too large. Keep it under 5 MB.' }, 400);
  const ext = extFromType(file.type);
  const base = safeName(rawName || file.name || 'signature-image');
  const key = `uploads/${base}.${ext}`;
  const body = await file.arrayBuffer();
  await env.SIG_ASSETS.put(key, body, { metadata: { contentType: file.type, fileName: `${base}.${ext}`, uploadedAt: new Date().toISOString() } });
  const origin = new URL(request.url).origin;
  return jsonResponse({ ok: true, name: `${base}.${ext}`, path: `/u/${base}.${ext}`, url: `${origin}/u/${base}.${ext}`, contentType: file.type, size: file.size });
}
async function serveUploadedAsset(pathname, env) {
  if (!env.SIG_ASSETS) return new Response('Missing Cloudflare KV binding: SIG_ASSETS', { status: 500 });
  const name = decodeURIComponent(pathname.replace(/^\/u\//, ''));
  if (!/^[a-z0-9][a-z0-9-_]*\.(jpg|jpeg|png|gif|webp)$/i.test(name)) return new Response('Invalid asset name', { status: 400 });
  const value = await env.SIG_ASSETS.getWithMetadata(`uploads/${name}`, { type: 'arrayBuffer' });
  if (!value || !value.value) return new Response('Not found', { status: 404 });
  return new Response(value.value, { headers: { 'content-type': value.metadata?.contentType || 'application/octet-stream', 'cache-control': 'public, max-age=31536000, immutable', 'access-control-allow-origin': '*' } });
}
async function listUploads(request, env) {
  if (!env.SIG_ASSETS) return jsonResponse({ error: 'Missing Cloudflare KV binding: SIG_ASSETS' }, 500);
  const origin = new URL(request.url).origin;
  const list = await env.SIG_ASSETS.list({ prefix: 'uploads/', limit: 100 });
  return jsonResponse({ uploads: list.keys.map(k => ({ name: k.name.replace('uploads/', ''), url: `${origin}/u/${k.name.replace('uploads/', '')}`, uploadedAt: k.metadata?.uploadedAt || null, contentType: k.metadata?.contentType || null })) });
}

export default { async fetch(request, env) {
  const url = new URL(request.url);
  if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '')) return Response.redirect(`${url.origin}/editor/`, 302);
  if (request.method === 'GET' && url.pathname === '/editor') return Response.redirect(`${url.origin}/editor/`, 302);
  if (request.method === 'POST' && url.pathname === '/api/upload') return serveUpload(request, env);
  if (request.method === 'GET' && url.pathname === '/api/list') return listUploads(request, env);
  if (request.method === 'GET' && url.pathname.startsWith('/u/')) return serveUploadedAsset(url.pathname, env);
  if (request.method === 'GET' && STATIC_HTML[url.pathname]) return htmlResponse(STATIC_HTML[url.pathname]);
  if (request.method === 'GET' && STATIC_ASSETS[url.pathname]) return staticAssetResponse(STATIC_ASSETS[url.pathname]);
  return new Response('Not found', { status: 404 });
} };
